import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { stripTypeScriptTypes } from 'node:module';
const source = stripTypeScriptTypes(await readFile(new URL('../../apps/mobile/src/catalogSnapshot.ts', import.meta.url), 'utf8'));
const { catalogRows, parseCatalogSnapshot, catalogMaxChars } = await import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
const now = Date.now();
const product = { id: 'phone', lojaId: 'vox', nome: 'Celular', sub: '128 GB', categoria: 'Celulares', preco: 999.9, estoque: 3, imgUrl: '/uploads/phone.webp', secret: 'must-not-persist' };
const raw = data => JSON.stringify({ version: 1, storeId: 'vox', savedAt: now, products: [product], ...data });
assert.equal(parseCatalogSnapshot(raw({}), now).products[0].preco, 999.9);
assert.equal('secret' in catalogRows([product], 'vox')[0], false);
assert.equal(catalogRows(Array.from({ length: 500 }, () => product), 'vox').length, 200);
for (const data of [{ version: 2 }, { savedAt: now + 1 }, { savedAt: now - 48 * 3600000 - 1 }, { storeId: 'other' }, { products: [{ ...product, preco: -1 }] }, { products: [{ ...product, estoque: 0.5 }] }, { products: [{ ...product, nome: 'x'.repeat(201) }] }]) assert.throws(() => parseCatalogSnapshot(raw(data), now));
assert.throws(() => parseCatalogSnapshot('x'.repeat(catalogMaxChars + 1), now));
assert.throws(() => parseCatalogSnapshot('{broken', now));
console.log('Offline catalog: bounded public fields, tenant isolation, expiry, future timestamp and malformed input passed.');
const fixture = globalThis.__voxOfflineFixture = { stored: null, error: null, store: 'vox', rows: [product], failStorage: false };
let loader = stripTypeScriptTypes(await readFile(new URL('../../apps/mobile/src/offlineCatalog.ts', import.meta.url), 'utf8'));
loader = loader.replace(/import .* from '@react-native-async-storage\/async-storage';/, `const AsyncStorage = { getItem: async () => globalThis.__voxOfflineFixture.stored, setItem: async (key, value) => { if (globalThis.__voxOfflineFixture.failStorage) throw new Error('Full'); globalThis.__voxOfflineFixture.stored = value; }, removeItem: async () => { globalThis.__voxOfflineFixture.stored = null; } };`);
loader = loader.replace(/import .* from '\.\/api';/, `export class ApiError extends Error { constructor(message, status) { super(message); this.status = status; } } const publicApiIdentity = 'https://fixture.invalid/api'; const request = async path => { const f = globalThis.__voxOfflineFixture; if (f.error) throw f.error; return path === '/loja' ? { id: f.store } : f.rows; };`);
loader = loader.replace(/from '\.\/catalogSnapshot'/, `from 'data:text/javascript;base64,${Buffer.from(source).toString('base64')}'`);
const { loadCatalog, ApiError } = await import(`data:text/javascript;base64,${Buffer.from(loader).toString('base64')}`);
assert.equal((await loadCatalog()).savedAt, null);
assert.equal(JSON.stringify(fixture.stored).includes('must-not-persist'), false);
fixture.error = new TypeError('Offline');
assert.equal((await loadCatalog()).products[0].id, 'phone');
assert.equal(typeof (await loadCatalog()).savedAt, 'number');
fixture.error = new ApiError('Missing', 404);
await assert.rejects(loadCatalog(), error => error.status === 404);
fixture.error = new TypeError('Offline'); fixture.stored = raw({ savedAt: now - 49 * 3600000 });
await assert.rejects(loadCatalog()); assert.equal(fixture.stored, null);
fixture.error = null; fixture.failStorage = true;
assert.equal((await loadCatalog()).products[0].id, 'phone');
assert.equal(fixture.stored, null);
delete globalThis.__voxOfflineFixture;
console.log('Offline catalog loader: live success, network fallback, no 404 fallback, expired cleanup and full storage passed.');
